(function(){
  const $=(s,e=document)=>e.querySelector(s);
  const $$=(s,e=document)=>Array.from(e.querySelectorAll(s));
  const view=$('#view'), toast=$('#toast'), modalRoot=$('#modalRoot'), importFile=$('#importFile'), installBtn=$('#installBtn');
  const state={route:'home',ibadahTab:'shalat',quranTab:'dashboard',profilePage:'menu',statsRange:30,selectedDate:keyOf(new Date()),settings:null,deferredInstall:null,backupPayload:null,calendarCursor:new Date()};

  const DOAS=[
    {title:'Sebelum makan',arab:'بِسْمِ اللّٰهِ',latin:'Bismillāh.',arti:'Dengan nama Allah.'},
    {title:'Sesudah makan',arab:'الْحَمْدُ لِلّٰهِ الَّذِي أَطْعَمَنِي هٰذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ',latin:'Alhamdulillāhilladzī ath‘amanī hādzā wa razaqanīhi min ghairi haulin minnī wa lā quwwah.',arti:'Segala puji bagi Allah yang telah memberi makanan ini dan rezeki kepadaku tanpa daya dan kekuatan dariku.'},
    {title:'Masuk rumah',arab:'بِسْمِ اللّٰهِ وَلَجْنَا وَبِسْمِ اللّٰهِ خَرَجْنَا وَعَلَى اللّٰهِ رَبِّنَا تَوَكَّلْنَا',latin:'Bismillāhi walajnā, wa bismillāhi kharajnā, wa ‘alallāhi rabbinā tawakkalnā.',arti:'Dengan nama Allah kami masuk, dengan nama Allah kami keluar, dan kepada Allah Tuhan kami, kami bertawakal.'},
    {title:'Keluar rumah',arab:'بِسْمِ اللّٰهِ تَوَكَّلْتُ عَلَى اللّٰهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ',latin:'Bismillāhi tawakkaltu ‘alallāh, lā haula wa lā quwwata illā billāh.',arti:'Dengan nama Allah, aku bertawakal kepada Allah. Tiada daya dan kekuatan kecuali dengan pertolongan Allah.'},
    {title:'Sebelum tidur',arab:'بِاسْمِكَ اللّٰهُمَّ أَحْيَا وَبِاسْمِكَ أَمُوتُ',latin:'Bismikallāhumma ahyā wa bismika amūt.',arti:'Dengan nama-Mu ya Allah aku hidup dan dengan nama-Mu aku mati.'},
    {title:'Bangun tidur',arab:'الْحَمْدُ لِلّٰهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ',latin:'Alhamdulillāhilladzī ahyānā ba‘da mā amātanā wa ilaihin nusyūr.',arti:'Segala puji bagi Allah yang menghidupkan kami setelah mematikan kami, dan kepada-Nya kebangkitan.'}
  ];

  function keyOf(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function fromKey(k){const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d)}
  function addDays(date,n){const d=new Date(date);d.setDate(d.getDate()+n);return d}
  function fmt(date,opts){return new Intl.DateTimeFormat('id-ID',opts).format(date)}
  function hijri(date){try{return new Intl.DateTimeFormat('id-ID-u-ca-islamic',{day:'numeric',month:'long',year:'numeric'}).format(date)}catch{return 'Tanggal Hijriah'}}
  function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
  function clamp(n,a,b){return Math.max(a,Math.min(b,n))}
  function sum(a,fn=x=>x){return a.reduce((t,x)=>t+Number(fn(x)||0),0)}
  function pct(a,b){return b?Math.round(a/b*100):0}
  function showToast(m){toast.textContent=m;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2200)}
  function closeModal(){modalRoot.innerHTML=''}
  function openModal(html){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal-card" data-stop>${html}</div></div>`}
  function applyTheme(){const s=state.settings;document.documentElement.style.setProperty('--accent',s.accent||'#195d63');document.body.classList.toggle('dark',!!s.darkMode);document.title=s.appName||'Atsar';$$('[data-brand]').forEach(el=>el.textContent=s.appName||'Atsar');$('meta[name="theme-color"]').setAttribute('content',s.accent||'#195d63')}

  async function dataset(){
    const [days,tilawah,murojaah,journal]=await Promise.all(['days','tilawah','murojaah','journal'].map(AtsarDB.getAll));
    const dayMap=Object.fromEntries(days.map(d=>[d.date,d]));
    const tilawahByDate={},murojaahByDate={};
    tilawah.forEach(x=>(tilawahByDate[x.date]||(tilawahByDate[x.date]=[])).push(x));
    murojaah.forEach(x=>(murojaahByDate[x.date]||(murojaahByDate[x.date]=[])).push(x));
    return {days,dayMap,tilawah,murojaah,journal,tilawahByDate,murojaahByDate};
  }
  async function dayData(date=state.selectedDate){return AtsarDB.getDay(date)}
  function tilawahPagesFor(ds,date){return sum(ds.tilawahByDate[date]||[],x=>x.pages)}
  function murojaahAyatFor(ds,date){return sum(ds.murojaahByDate[date]||[],x=>{const a=Number(x.startAyah||0),b=Number(x.endAyah||0);return a&&b&&b>=a?b-a+1:0})}
  function murojaahPagesFor(ds,date){return sum(ds.murojaahByDate[date]||[],x=>x.pages||((x.startPage&&x.endPage)?x.endPage-x.startPage+1:0))}
  function hasDayActivity(day,ds,date){if(!day)return tilawahPagesFor(ds,date)>0||murojaahAyatFor(ds,date)>0;return Object.values(day.prayers||{}).some(p=>p.done||p.qab||p.bad)||(day.sunnah?.dhuha||0)>0||(day.sunnah?.tahajud||0)>0||day.sunnah?.witir||day.fast?.active||(day.dzikir?.pagi||0)>0||(day.dzikir?.petang||0)>0||Object.values(day.custom||{}).some(Boolean)||tilawahPagesFor(ds,date)>0||murojaahAyatFor(ds,date)>0}
  function prayerCount(day){return Object.values(day?.prayers||{}).filter(p=>p.done).length}
  function rawatibCount(day){let n=0;Object.entries(day?.prayers||{}).forEach(([id,p])=>{const slots=state.settings.rawatib[id]||[];if(slots.includes('qab')&&p.qab)n++;if(slots.includes('bad')&&p.bad)n++});return n}
  function nextPrayer(){const now=new Date();for(const id of ['subuh','dzuhur','ashar','maghrib','isya']){const [h,m]=(state.settings.prayerTimes[id]||'00:00').split(':').map(Number);const t=new Date(now);t.setHours(h,m,0,0);if(t>now)return{id,label:state.settings.prayerLabels[id],time:state.settings.prayerTimes[id]}}return{id:'subuh',label:'Subuh',time:state.settings.prayerTimes.subuh,tomorrow:true}}

  function lastDates(n,end=new Date()){return Array.from({length:n},(_,i)=>addDays(end,-(n-1-i)))}
  function dateStrip(ds){const today=keyOf(new Date());return `<div class="date-strip">${lastDates(7).map(d=>{const k=keyOf(d),active=hasDayActivity(ds.dayMap[k],ds,k);return `<button class="date-chip ${k===state.selectedDate?'selected':''} ${k===today?'today':''}" data-date="${k}"><strong>${d.getDate()}</strong><span>${fmt(d,{weekday:'short'}).replace('.','')}</span>${active?'<i class="dot"></i>':''}</button>`}).join('')}</div>`}
  function sectionHead(title,sub=''){return `<div class="section-title"><h2>${title}</h2>${sub?`<span class="muted small">${sub}</span>`:''}</div>`}
  function emptyState(icon,title,desc,action=''){return `<div class="card empty-state"><div class="big-icon">${icon}</div><h3>${title}</h3><p class="muted">${desc}</p>${action}</div>`}
  function routeBack(label='Kembali'){return `<button class="back-btn" data-action="profile-menu">← ${label}</button>`}

  function prayerBlock(id,p){const label=state.settings.prayerLabels[id],slots=state.settings.rawatib[id]||[];return `<div class="prayer-block">
    <div class="prayer-head"><div><div class="prayer-name">${esc(label)}</div><div class="prayer-time">${esc(state.settings.prayerTimes[id])}</div></div><button class="check-circle ${p.done?'done':''}" data-action="toggle-prayer" data-prayer="${id}">${p.done?'✓':''}</button></div>
    ${p.done?`<div class="mode-row">${[['sendiri','Sendiri'],['jamaah','Jamaah'],['masjid','Jamaah di Masjid']].map(([v,t])=>`<button class="pill ${p.mode===v?'active':''}" data-action="prayer-mode" data-prayer="${id}" data-mode="${v}">${t}</button>`).join('')}</div>`:''}
    ${slots.map(slot=>`<div class="rawatib-row"><span>☆ ${slot==='qab'?'Qabliyah':'Ba’diyah'} ${esc(label)}${id==='ashar'&&slot==='qab'?'<small> ghairu muakkadah</small>':''}</span><button class="switch ${p[slot]?'on':''}" data-action="rawatib" data-prayer="${id}" data-slot="${slot}"></button></div>`).join('')}
  </div>`}

  function ramadanInfo(){const h=hijri(new Date());const is=/ramadan|ramaḍān/i.test(h);const m=h.match(/(\d+)/);return {is,day:m?Number(m[1]):null,label:h}}
  async function home(){const ds=await dataset(),day=await dayData(),d=fromKey(state.selectedDate),isToday=state.selectedDate===keyOf(new Date()),np=nextPrayer(),tp=tilawahPagesFor(ds,state.selectedDate),ma=murojaahAyatFor(ds,state.selectedDate);const insight=weeklyInsight(ds),ram=ramadanInfo();return `
    <section class="hero"><h1>Assalamu'alaikum, ${esc(state.settings.nickname)}</h1><div class="date-line">▣ ${fmt(new Date(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · ${hijri(new Date())}</div></section>
    <section class="card next-prayer"><div class="row between gap-12"><div><div class="muted small">Waktu shalat berikutnya</div><div class="time">${esc(np.label)} ${esc(np.time)}</div><div class="muted small">${esc(state.settings.location)}</div></div><button class="refresh-orb" data-action="render">↻</button></div></section>
    ${ram.is?`<section class="card pad ramadan-card"><div><span class="eyebrow">RAMADAN</span><h2>Hari ke-${ram.day||'–'}</h2><p>Puasa ${day.fast?.active?'✓':'○'} · Tilawah ${tp} hlm · Murojaah ${ma} ayat</p></div><span class="ramadan-moon">☾</span></section>`:''}
    ${sectionHead('Ringkasan Ibadah',isToday?'hari ini':fmt(d,{day:'numeric',month:'short'}))}
    <div class="summary-scroll"><article class="summary-card teal"><span>Shalat</span><strong>${prayerCount(day)}/5</strong><small>tercatat</small></article><article class="summary-card purple"><span>Rawatib</span><strong>${rawatibCount(day)}</strong><small>amalan</small></article><article class="summary-card blue"><span>Tilawah</span><strong>${tp}</strong><small>halaman</small></article><article class="summary-card gold"><span>Murojaah</span><strong>${ma}</strong><small>ayat</small></article></div>
    ${sectionHead('Hari Ini')}${dateStrip(ds)}
    <div class="home-grid"><div class="card compact-card"><div class="mini-heading">Target hari ini</div>${await targetSummary(ds,state.selectedDate)}</div><div class="card compact-card"><div class="mini-heading">Insight pekan ini</div><p class="insight-text">${insight}</p><button class="text-action" data-route="aktivitas">Lihat ringkasan →</button></div></div>
    ${sectionHead('Shalat')}
    <div class="card prayer-list">${Object.keys(state.settings.prayerTimes).map(id=>prayerBlock(id,day.prayers[id])).join('')}</div>
  `}

  function targetChecks(day,ds,date){const t=state.settings.targets||{};const rows=[];if(t.prayer5)rows.push(['Shalat 5 waktu',prayerCount(day)>=5]);if(t.tilawah)rows.push([`Tilawah ≥ ${t.tilawahPages||5} hlm`,tilawahPagesFor(ds,date)>=(t.tilawahPages||5)]);if(t.dzikirPagi)rows.push(['Dzikir pagi',(day.dzikir?.pagi||0)>0]);if(t.dhuha)rows.push(['Dhuha',(day.sunnah?.dhuha||0)>0]);if(t.murojaah)rows.push([`Murojaah ≥ ${t.murojaahAyat||10} ayat`,murojaahAyatFor(ds,date)>=(t.murojaahAyat||10)]);return rows}
  async function targetSummary(ds,date){const day=ds.dayMap[date]||AtsarDB.emptyDay();const rows=targetChecks(day,ds,date);if(!rows.length)return `<p class="muted small">Belum ada target aktif. Atur dari Profil → Target & Streak.</p>`;return `<div class="target-list">${rows.map(([n,ok])=>`<div><span class="status-dot ${ok?'ok':''}">${ok?'✓':'○'}</span><span>${n}</span></div>`).join('')}</div>`}
  function dayGoalMet(day,ds,date){const rows=targetChecks(day,ds,date);return rows.length?rows.every(x=>x[1]):hasDayActivity(day,ds,date)}
  function streakFrom(ds,kind='target'){let n=0,d=new Date();for(let i=0;i<1500;i++){const k=keyOf(d),day=ds.dayMap[k]||AtsarDB.emptyDay();let ok=kind==='tilawah'?tilawahPagesFor(ds,k)>0:kind==='murojaah'?murojaahAyatFor(ds,k)>0:dayGoalMet(day,ds,k);if(!ok)break;n++;d=addDays(d,-1)}return n}

  async function ibadah(){const ds=await dataset(),day=await dayData();return `<section class="page-head"><h1>Ibadah</h1><p>Catat ibadah harianmu tanpa penilaian atau ranking.</p></section><div class="tabs five">${[['shalat','Shalat'],['sunnah','Sunnah'],['puasa','Puasa'],['dzikir','Dzikir'],['custom','Custom']].map(([id,l])=>`<button class="tab-btn ${state.ibadahTab===id?'active':''}" data-ibadah-tab="${id}">${l}</button>`).join('')}</div>${dateStrip(ds)}<p class="muted strip-note">Menampilkan <b>${state.selectedDate===keyOf(new Date())?'Hari Ini':fmt(fromKey(state.selectedDate),{day:'numeric',month:'long'})}</b> — pilih tanggal lain untuk edit catatan.</p>${state.ibadahTab==='shalat'?`<div class="card prayer-list">${Object.keys(state.settings.prayerTimes).map(id=>prayerBlock(id,day.prayers[id])).join('')}</div>`:state.ibadahTab==='sunnah'?sunnahUI(day):state.ibadahTab==='puasa'?puasaUI(day,ds):state.ibadahTab==='dzikir'?dzikirUI(day):customDailyUI(day)}`}
  function sunnahUI(day){return `<div class="stack">${state.settings.sunnah.map(x=>`<div class="card sunnah-card"><div class="emoji-box">${x.icon}</div><div><h3>${x.name}</h3><p>${x.note}</p></div>${x.mode==='rakaat'?`<div class="counter"><button data-action="sunnah-dec" data-id="${x.id}">−</button><div><strong>${day.sunnah[x.id]||0}</strong><small>rakaat</small></div><button data-action="sunnah-inc" data-id="${x.id}">+</button></div>`:`<button class="switch ${day.sunnah[x.id]?'on':''}" data-action="sunnah-toggle" data-id="${x.id}"></button>`}</div>`).join('')}</div>`}
  function puasaUI(day,ds){const doneQadha=ds.days.filter(d=>d.fast?.active&&d.fast.type==='Qadha').length,left=Math.max(0,Number(state.settings.qadhaInitial||0)-doneQadha);return `<div class="card pad"><div class="row between"><div><h2>Puasa hari ini</h2><p class="muted">${day.fast.active?esc(day.fast.type):'Belum dicatat'}</p></div><button class="switch ${day.fast.active?'on':''}" data-action="fast-toggle"></button></div><div class="fast-options">${state.settings.fastTypes.map(t=>`<button class="fast-chip ${day.fast.type===t&&day.fast.active?'active':''}" data-action="fast-type" data-fast="${esc(t)}">${esc(t)}</button>`).join('')}</div></div><div class="card pad qadha-mini"><div><span class="eyebrow">QADHA PUASA</span><h2>${left} hari tersisa</h2><p class="muted">Utang awal ${state.settings.qadhaInitial||0} hari · selesai ${doneQadha} hari</p></div><button class="ghost-btn" data-action="open-qadha">Atur</button></div>`}
  function dzikirUI(day){const target=state.settings.dzikirTargets;return `<div class="stack">${['pagi','petang'].map(k=>{const v=day.dzikir[k]||0,t=target[k]||100;return `<div class="card pad"><div class="row between"><div><h2>Dzikir ${k}</h2><p class="muted">${v} / ${t}</p></div><div class="ring-mini" style="--p:${clamp(v/t*100,0,100)}">${pct(v,t)}%</div></div><div class="quick-add"><button data-action="dzikir-add" data-kind="${k}" data-num="1">+1</button><button data-action="dzikir-add" data-kind="${k}" data-num="10">+10</button><button data-action="dzikir-add" data-kind="${k}" data-num="33">+33</button><button data-action="dzikir-reset" data-kind="${k}">Reset</button></div></div>`}).join('')}</div>`}
  function customDailyUI(day){const items=state.settings.customHabits||[];if(!items.length)return emptyState('＋','Belum ada ibadah custom','Tambahkan kebiasaan seperti Al-Kahfi Jumat, sedekah, shalawat, kajian, atau hafalan.',`<button class="primary-btn" data-action="profile-custom">Tambah ibadah custom</button>`);return `<div class="stack">${items.map(h=>{const v=day.custom?.[h.id]||0;return `<div class="card custom-card"><div><h3>${esc(h.name)}</h3><p>${esc(h.unit||'Checklist')}${h.target?` · target ${h.target}`:''}</p></div>${h.type==='check'?`<button class="check-circle ${v?'done':''}" data-action="custom-check" data-id="${h.id}">${v?'✓':''}</button>`:`<div class="counter"><button data-action="custom-dec" data-id="${h.id}">−</button><strong>${v}</strong><button data-action="custom-inc" data-id="${h.id}">+</button></div>`}</div>`}).join('')}<button class="ghost-btn full" data-action="profile-custom">Kelola ibadah custom</button></div>`}

  function quranTabs(){return `<div class="tabs quran-tabs">${[['dashboard','Ringkas'],['tilawah','Tilawah'],['murojaah','Murojaah'],['riwayat','Riwayat'],['khatam','Khatam']].map(([id,l])=>`<button class="tab-btn ${state.quranTab===id?'active':''}" data-quran-tab="${id}">${l}</button>`).join('')}</div>`}
  async function quran(){const ds=await dataset();return `<section class="page-head"><h1>Qur'an</h1><p>Tilawah, khatam, dan murojaah dalam satu perjalanan.</p></section>${quranTabs()}${state.quranTab==='dashboard'?quranDashboard(ds):state.quranTab==='tilawah'?tilawahUI(ds):state.quranTab==='murojaah'?murojaahUI(ds):state.quranTab==='riwayat'?quranHistory(ds):khatamUI(ds)}`}
  function quranMetrics(ds){const total=sum(ds.tilawah,x=>x.pages),cycle=Math.floor(total/604)+1,current=total%604,percent=pct(current,604),today=tilawahPagesFor(ds,keyOf(new Date())),readingDays=new Set(ds.tilawah.filter(x=>x.pages>0).map(x=>x.date)).size,avg=readingDays?total/readingDays:0;return{total,cycle,current,percent,today,readingDays,avg}}
  function dueMurojaah(ds){const today=keyOf(new Date());const latest={};ds.murojaah.slice().sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))).forEach(x=>{const k=`${x.surah}|${x.startAyah||''}|${x.endAyah||''}|${x.startPage||''}|${x.endPage||''}`;latest[k]=x});return Object.values(latest).filter(x=>x.nextReview&&x.nextReview<=today).sort((a,b)=>xdate(a.nextReview)-xdate(b.nextReview));function xdate(k){return fromKey(k).getTime()}}
  function quranDashboard(ds){const m=quranMetrics(ds),due=dueMurojaah(ds),mt=sum(ds.murojaah,x=>x.pages||0);const surahs=[...new Set(ds.tilawah.map(x=>x.surah).filter(Boolean))];return `<div class="stack"><div class="card pad hero-progress"><div class="row between"><div><span class="eyebrow">PROGRESS KHATAM</span><h2>Khatam ke-${m.cycle}</h2></div><div class="badge">${m.percent}%</div></div><div class="progress-track"><div class="progress-fill" style="width:${m.percent}%"></div></div><div class="row between small"><span>${m.current} / 604 halaman</span><span>${604-m.current} halaman lagi</span></div></div><div class="stat-grid four"><div class="stat-box"><strong>${m.today}</strong><span>hlm hari ini</span></div><div class="stat-box"><strong>${m.total}</strong><span>total halaman</span></div><div class="stat-box"><strong>${m.readingDays}</strong><span>hari membaca</span></div><div class="stat-box"><strong>${due.length}</strong><span>murojaah jatuh tempo</span></div></div><div class="action-grid"><button class="feature-card" data-quran-tab="tilawah"><span>📖</span><b>Catat Tilawah</b><small>Quick add atau detail bacaan</small></button><button class="feature-card" data-quran-tab="murojaah"><span>🧠</span><b>Catat Murojaah</b><small>${due.length?due.length+' bagian perlu diulang':'Hafalan terjadwal'}</small></button></div>${sectionHead('Sudah dibaca')}${surahs.length?`<div class="card pad read-surahs">${surahs.slice(-8).reverse().map(s=>`<span>✓ ${esc(s)}</span>`).join('')}${surahs.length>8?`<small>+${surahs.length-8} surah lain</small>`:''}</div>`:emptyState('📚','Belum ada riwayat bacaan','Catat tilawah detail agar Atsar bisa merekap surah, halaman, dan perjalanan khatammu.')}${due.length?`${sectionHead('Murojaah hari ini')}<div class="card settings-list">${due.slice(0,5).map(x=>murojaahRow(x,true)).join('')}</div>`:''}</div>`}
  function surahOptions(selected=''){return `<option value="">Pilih surah</option>${window.ATSAR_SURAHS.map(s=>`<option ${s===selected?'selected':''}>${esc(s)}</option>`).join('')}`}
  function tilawahUI(ds){const today=keyOf(new Date()),todayPages=tilawahPagesFor(ds,today),m=quranMetrics(ds);return `<div class="stack"><div class="card pad"><div class="row between"><div><h2>Tambah halaman hari ini</h2><p class="muted"><b>${todayPages}</b> halaman sudah tercatat</p></div><span class="streak-badge">🔥 ${streakFrom(ds,'tilawah')} hari</span></div><div class="quick-add"><button data-action="quick-tilawah" data-num="1">+1</button><button data-action="quick-tilawah" data-num="2">+2</button><button data-action="quick-tilawah" data-num="5">+5</button><button data-action="quick-tilawah" data-num="10">+10</button></div><div class="input-row"><input id="quickPages" type="number" min="1" placeholder="Jumlah lain"><button class="primary-btn" data-action="quick-tilawah-custom">Tambah</button></div></div><div class="card pad"><span class="eyebrow">CATAT DETAIL BACAAN</span><h2>Sudah baca apa?</h2><form id="tilawahForm" class="form-grid"><label>Surah<select class="form-select" name="surah" required>${surahOptions()}</select></label><div class="two"><label>Juz<input class="form-input" type="number" min="1" max="30" name="juz" placeholder="1–30"></label><label>Total halaman<input class="form-input" type="number" min="1" name="pages" required></label></div><div class="two"><label>Halaman awal<input class="form-input" type="number" min="1" max="604" name="startPage"></label><label>Halaman akhir<input class="form-input" type="number" min="1" max="604" name="endPage"></label></div><label>Catatan<textarea name="note" rows="2" placeholder="Opsional"></textarea></label><button class="primary-btn">Simpan tilawah</button></form></div><div class="card pad"><div class="row between"><div><span class="eyebrow">KHATAM KE-${m.cycle}</span><h2>${m.current} / 604</h2></div><b>${m.percent}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${m.percent}%"></div></div></div></div>`}
  function qualityMeta(q){return {weak:['Lemah','😣',1],fair:['Cukup','😐',3],good:['Baik','🙂',7],fluent:['Lancar','✨',14]}[q]||['-', '○',3]}
  function murojaahUI(ds){const due=dueMurojaah(ds),today=keyOf(new Date()),todayAyat=murojaahAyatFor(ds,today);return `<div class="stack">${due.length?`<div class="card pad"><div class="row between"><div><span class="eyebrow">PERLU DIULANG</span><h2>${due.length} bagian hari ini</h2></div><span class="streak-badge">🔥 ${streakFrom(ds,'murojaah')} hari</span></div><div class="due-list">${due.slice(0,6).map(x=>murojaahRow(x,true)).join('')}</div></div>`:''}<div class="card pad"><span class="eyebrow">CATAT MUROJAAH</span><h2>${todayAyat} ayat hari ini</h2><form id="murojaahForm" class="form-grid"><label>Surah<select class="form-select" name="surah" required>${surahOptions()}</select></label><div class="two"><label>Ayat awal<input class="form-input" type="number" min="1" name="startAyah"></label><label>Ayat akhir<input class="form-input" type="number" min="1" name="endAyah"></label></div><div class="two"><label>Halaman awal<input class="form-input" type="number" min="1" max="604" name="startPage"></label><label>Halaman akhir<input class="form-input" type="number" min="1" max="604" name="endPage"></label></div><label>Kualitas hafalan<div class="quality-grid">${[['weak','😣','Lemah'],['fair','😐','Cukup'],['good','🙂','Baik'],['fluent','✨','Lancar']].map(([v,e,l])=>`<label class="quality-choice"><input type="radio" name="quality" value="${v}" ${v==='fair'?'checked':''}><span>${e}<b>${l}</b></span></label>`).join('')}</div></label><label>Catatan<textarea name="note" rows="2" placeholder="Contoh: ayat 8–10 masih tertukar"></textarea></label><button class="primary-btn">Simpan murojaah</button></form></div></div>`}
  function murojaahRow(x,compact=false){const [label,emoji]=qualityMeta(x.quality);return `<div class="history-row"><div class="history-icon">${emoji}</div><div class="grow"><b>${esc(x.surah||'Murojaah')}</b><small>${x.startAyah?`Ayat ${x.startAyah}${x.endAyah?`–${x.endAyah}`:''}`:x.startPage?`Hal. ${x.startPage}${x.endPage?`–${x.endPage}`:''}`:'Bagian tercatat'} · ${label}</small>${x.nextReview?`<small>Ulang ${x.nextReview<=keyOf(new Date())?'hari ini':fmt(fromKey(x.nextReview),{day:'numeric',month:'short'})}</small>`:''}</div>${!compact?`<button class="icon-btn danger-text" data-action="delete-murojaah" data-id="${x.id}">×</button>`:''}</div>`}
  function quranHistory(ds){const rows=[...ds.tilawah.map(x=>({...x,_type:'tilawah'})),...ds.murojaah.map(x=>({...x,_type:'murojaah'}))].sort((a,b)=>(b.createdAt||b.date).localeCompare(a.createdAt||a.date));if(!rows.length)return emptyState('◷','Belum ada riwayat','Catatan tilawah dan murojaah akan muncul di sini.');return `<div class="card settings-list history-list">${rows.map(x=>x._type==='tilawah'?`<div class="history-row"><div class="history-icon">📖</div><div class="grow"><b>${x.surah?esc(x.surah):'Tilawah'}</b><small>${fmt(fromKey(x.date),{day:'numeric',month:'short',year:'numeric'})} · ${x.pages} halaman${x.startPage?` · hal. ${x.startPage}${x.endPage?`–${x.endPage}`:''}`:''}</small>${x.note?`<small>${esc(x.note)}</small>`:''}</div><button class="icon-btn danger-text" data-action="delete-tilawah" data-id="${x.id}">×</button></div>`:murojaahRow(x)).join('')}</div>`}
  function computeKhatam(ds){const sessions=ds.tilawah.slice().sort((a,b)=>(a.createdAt||a.date).localeCompare(b.createdAt||b.date));let running=0,n=1;const history=[];for(const s of sessions){running+=Number(s.pages||0);while(running>=604){history.push({n,date:s.date});running-=604;n++}}return{history,current:n,pages:running}}
  function khatamUI(ds){const k=computeKhatam(ds),remaining=604-k.pages;const last30=ds.tilawah.filter(x=>fromKey(x.date)>=addDays(new Date(),-29));const activeDays=new Set(last30.map(x=>x.date)).size,avg=activeDays?sum(last30,x=>x.pages)/activeDays:0,eta=avg?Math.ceil(remaining/avg):null;return `<div class="stack"><div class="card pad hero-progress"><span class="eyebrow">PERJALANAN KHATAM</span><div class="row between"><h2>Khatam ke-${k.current}</h2><b>${pct(k.pages,604)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${pct(k.pages,604)}%"></div></div><p>${k.pages} / 604 halaman · ${remaining} halaman lagi</p>${eta?`<p class="muted small">Dengan rata-rata ${avg.toFixed(1).replace('.',',')} hlm/hari baca, estimasi ± ${eta} hari baca lagi.</p>`:''}</div>${sectionHead('Riwayat khatam')}${k.history.length?`<div class="card settings-list">${k.history.slice().reverse().map(x=>`<div class="setting-row simple"><div class="setting-icon">🎉</div><div><b>Khatam ke-${x.n}</b><p>${fmt(fromKey(x.date),{day:'numeric',month:'long',year:'numeric'})}</p></div></div>`).join('')}</div>`:emptyState('🌱','Perjalanan baru dimulai','Setiap halaman yang dicatat akan mengisi progress khatam tanpa menghapus riwayat sebelumnya.')}</div>`}

  function weeklyInsight(ds){const a=lastDates(7),b=lastDates(7,addDays(new Date(),-7)),x=sum(a,d=>tilawahPagesFor(ds,keyOf(d))),y=sum(b,d=>tilawahPagesFor(ds,keyOf(d)));if(x===0&&y===0)return 'Mulai catat ibadahmu. Insight akan muncul setelah ada beberapa hari data.';if(y===0&&x>0)return `Pekan ini kamu mencatat ${x} halaman tilawah. Awal yang baik untuk melihat pola pribadimu.`;const diff=Math.round((x-y)/Math.max(y,1)*100);return `Tilawah pekan ini ${x} halaman, ${diff>=0?'naik':'turun'} ${Math.abs(diff)}% dibanding pekan sebelumnya. Data ini untuk refleksi, bukan penilaian.`}
  function monthlyDays(cursor=state.calendarCursor){const y=cursor.getFullYear(),m=cursor.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),lead=(first.getDay()+6)%7,cells=[];for(let i=0;i<lead;i++)cells.push(null);for(let d=1;d<=last.getDate();d++)cells.push(new Date(y,m,d));while(cells.length%7)cells.push(null);return cells}
  function activityLevel(day,ds,k){if(!hasDayActivity(day,ds,k))return 0;let score=prayerCount(day)+(tilawahPagesFor(ds,k)>0?2:0)+(murojaahAyatFor(ds,k)>0?1:0)+(day.fast?.active?1:0)+((day.sunnah?.dhuha||0)>0?1:0);return score>=8?3:score>=5?2:1}
  async function aktivitas(){const ds=await dataset(),days=lastDates(7),active=days.filter(d=>hasDayActivity(ds.dayMap[keyOf(d)],ds,keyOf(d))).length,prayers=sum(days,d=>prayerCount(ds.dayMap[keyOf(d)]||AtsarDB.emptyDay())),til=sum(days,d=>tilawahPagesFor(ds,keyOf(d))),mur=sum(days,d=>murojaahAyatFor(ds,keyOf(d)));return `<section class="page-head"><h1>Aktivitas</h1><p>Riwayat, ringkasan pekan, dan kalender jejakmu.</p></section><div class="card pad weekly-card"><div class="row between"><div><span class="eyebrow">7 HARI TERAKHIR</span><h2>Pekanmu di Atsar</h2></div><span class="streak-badge">🔥 ${streakFrom(ds)} hari</span></div><div class="stat-grid four"><div class="stat-box"><strong>${active}/7</strong><span>hari aktif</span></div><div class="stat-box"><strong>${prayers}</strong><span>shalat</span></div><div class="stat-box"><strong>${til}</strong><span>hlm tilawah</span></div><div class="stat-box"><strong>${mur}</strong><span>ayat murojaah</span></div></div><p class="insight-text">${weeklyInsight(ds)}</p></div>${sectionHead('Kalender ibadah')} ${calendarUI(ds)} ${sectionHead('Catatan refleksi')} ${await journalUI(ds)} ${sectionHead('Milestone pribadi')} ${achievementUI(ds)} ${sectionHead('Aktivitas terbaru')} ${activityTimeline(ds)}`}
  function achievementUI(ds){const totalTil=sum(ds.tilawah,x=>x.pages),kh=computeKhatam(ds).history.length,active=ds.days.filter(d=>hasDayActivity(d,ds,d.date)).length,tah=ds.days.filter(d=>(d.sunnah?.tahajud||0)>0).length;const a=[['📖','100 halaman tilawah',totalTil>=100],['🎉','Khatam pertama',kh>=1],['🔥','30 hari aktif',active>=30],['🌙','Tahajud 10 kali',tah>=10]];return `<div class="achievement-grid">${a.map(([i,t,ok])=>`<div class="achievement ${ok?'unlocked':''}"><span>${i}</span><b>${t}</b><small>${ok?'Tercapai':'Belum tercapai'}</small></div>`).join('')}</div>`}
  function calendarUI(ds){const cells=monthlyDays(),title=fmt(state.calendarCursor,{month:'long',year:'numeric'});return `<div class="card pad"><div class="calendar-head"><button class="icon-btn" data-action="cal-prev">‹</button><b>${title}</b><button class="icon-btn" data-action="cal-next">›</button></div><div class="calendar-week">${['S','S','R','K','J','S','M'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.map(d=>{if(!d)return '<span></span>';const k=keyOf(d),l=activityLevel(ds.dayMap[k],ds,k);return `<button class="cal-day level-${l} ${k===keyOf(new Date())?'today':''}" data-date="${k}">${d.getDate()}</button>`}).join('')}</div><div class="calendar-legend"><span>○ belum</span><span>● sebagian</span><span>● aktif</span><span>● lengkap</span></div></div>`}
  async function journalUI(ds){const current=ds.journal.find(x=>x.date===state.selectedDate);return `<div class="card pad"><div class="row between"><div><b>${fmt(fromKey(state.selectedDate),{day:'numeric',month:'long',year:'numeric'})}</b><p class="muted small">Catatan ini hanya tersimpan di perangkat/backup milikmu.</p></div></div><textarea id="journalText" rows="3" placeholder="Apa yang ingin dijaga atau diperbaiki besok?">${esc(current?.text||'')}</textarea><button class="primary-btn top-gap" data-action="save-journal">Simpan catatan</button></div>`}
  function activityTimeline(ds){const rows=[];ds.tilawah.forEach(x=>rows.push({date:x.date,createdAt:x.createdAt,type:'📖',title:`Tilawah ${x.pages} halaman`,sub:x.surah||'Quick add'}));ds.murojaah.forEach(x=>rows.push({date:x.date,createdAt:x.createdAt,type:'🧠',title:`Murojaah ${x.surah||''}`,sub:qualityMeta(x.quality)[0]}));ds.days.forEach(d=>{const p=prayerCount(d);if(p)rows.push({date:d.date,createdAt:d.date+'T23:00:00',type:'✓',title:`${p}/5 shalat tercatat`,sub:d.fast?.active?`Puasa ${d.fast.type}`:''})});rows.sort((a,b)=>(b.createdAt||b.date).localeCompare(a.createdAt||a.date));if(!rows.length)return emptyState('◷','Belum ada aktivitas','Mulai mencatat dan riwayat akan muncul di sini.');return `<div class="card settings-list">${rows.slice(0,20).map(x=>`<div class="history-row"><div class="history-icon">${x.type}</div><div><b>${esc(x.title)}</b><small>${fmt(fromKey(x.date),{day:'numeric',month:'short'})}${x.sub?' · '+esc(x.sub):''}</small></div></div>`).join('')}</div>`}

  async function profil(){const ds=await dataset();if(state.profilePage!=='menu')return profileSub(ds);return `<section class="page-head"><h1>Profil & Pengaturan</h1></section><div class="card profile-head"><div class="avatar">${esc((state.settings.nickname||'A')[0].toUpperCase())}</div><div><span class="muted">Nama panggilan</span><h2>${esc(state.settings.nickname)}</h2><p>${esc(state.settings.appName)} · ${esc(state.settings.tagline)}</p></div></div><div class="profile-sections"><div><span class="eyebrow">PERJALANAN</span><div class="card settings-list">${profileRow('▥','Statistik ibadah','Tren 7/30/90 hari & breakdown','stats')}${profileRow('🔥','Target & Streak',`Streak saat ini ${streakFrom(ds)} hari`,'targets')}${profileRow('▦','Kalender Ibadah','Lihat pola aktivitas bulanan','calendar')}</div></div><div><span class="eyebrow">AL-QUR\'AN & PUASA</span><div class="card settings-list">${profileRow('📖','Progress Tilawah',`${quranMetrics(ds).total} halaman tercatat`,'quran')}${profileRow('🧠','Murojaah','Tracking hafalan & review terjadwal','murojaah')}${profileRow('☾','Qadha Puasa','Kelola utang dan pelunasan qadha','qadha')}</div></div><div><span class="eyebrow">PERSONAL</span><div class="card settings-list">${profileRow('▤','Kumpulan Doa','Arab, transliterasi Indonesia, arti','doa')}${profileRow('＋','Ibadah Custom','Buat tracker sendiri','custom')}</div></div><div><span class="eyebrow">PENGATURAN</span><div class="card settings-list">${profileRow('⚙','Personalisasi','Nama, lokasi, target Qur\'an','personal')}${profileRow('◷','Waktu Shalat','Edit waktu shalat manual','prayer')}${profileRow(state.settings.darkMode?'☾':'☀','Tampilan',state.settings.darkMode?'Mode gelap':'Mode terang','display')}${profileRow('⇅','Data & Backup','Export, import, restore','backup')}</div></div></div>`}
  function profileRow(icon,title,sub,page){return `<button class="setting-row button-row" data-profile-page="${page}"><span class="setting-icon">${icon}</span><span><b>${title}</b><small>${sub}</small></span><span>›</span></button>`}
  async function profileSub(ds){switch(state.profilePage){case'stats':return statsPage(ds);case'targets':return targetsPage(ds);case'calendar':return `${routeBack()}<section class="page-head compact"><h1>Kalender Ibadah</h1></section>${calendarUI(ds)}`;case'quran':state.route='quran';state.quranTab='dashboard';state.profilePage='menu';return quran();case'murojaah':state.route='quran';state.quranTab='murojaah';state.profilePage='menu';return quran();case'qadha':return qadhaPage(ds);case'doa':return doaPage();case'custom':return customManager();case'personal':return personalization();case'prayer':return prayerSettings();case'display':return displaySettings();case'backup':return backupPage(ds);default:return ''}}

  function rangeDates(n){return lastDates(n)}
  function statsPage(ds){const range=state.statsRange||30,dates=rangeDates(range),days=dates.map(d=>ds.dayMap[keyOf(d)]||AtsarDB.emptyDay()),active=dates.filter(d=>hasDayActivity(ds.dayMap[keyOf(d)],ds,keyOf(d))).length,totalPrayer=sum(days,prayerCount),jamaah=sum(days,d=>Object.values(d.prayers||{}).filter(p=>p.done&&(p.mode==='jamaah'||p.mode==='masjid')).length),masjid=sum(days,d=>Object.values(d.prayers||{}).filter(p=>p.done&&p.mode==='masjid').length),raw=sum(days,rawatibCount),dhuha=days.filter(d=>(d.sunnah?.dhuha||0)>0).length,tahajud=days.filter(d=>(d.sunnah?.tahajud||0)>0).length,witir=days.filter(d=>d.sunnah?.witir).length,fast=days.filter(d=>d.fast?.active).length,til=sum(dates,d=>tilawahPagesFor(ds,keyOf(d))),murAyat=sum(dates,d=>murojaahAyatFor(ds,keyOf(d))),murPages=sum(dates,d=>murojaahPagesFor(ds,keyOf(d))),prayers=['subuh','dzuhur','ashar','maghrib','isya'].map(id=>({id,label:state.settings.prayerLabels[id],done:days.filter(d=>d.prayers?.[id]?.done).length,jamaah:days.filter(d=>d.prayers?.[id]?.done&&['jamaah','masjid'].includes(d.prayers[id].mode)).length,masjid:days.filter(d=>d.prayers?.[id]?.done&&d.prayers[id].mode==='masjid').length}));return `${routeBack()}<section class="page-head compact"><h1>Statistik Ibadah</h1><p>${range} hari terakhir · untuk refleksi pribadi, bukan skor ibadah.</p></section><div class="range-pills">${[7,30,90].map(n=>`<button class="${range===n?'active':''}" data-action="stats-range" data-range="${n}">${n} Hari</button>`).join('')}</div><div class="stat-grid four"><div class="stat-box"><strong>${active}/${range}</strong><span>hari aktif</span></div><div class="stat-box"><strong>${totalPrayer}</strong><span>shalat tercatat</span></div><div class="stat-box"><strong>${til}</strong><span>hlm tilawah</span></div><div class="stat-box"><strong>${murAyat}</strong><span>ayat murojaah</span></div></div>${sectionHead(`Konsistensi ${range} hari`)}<div class="card pad"><div class="heatmap">${dates.map(d=>{const k=keyOf(d),l=activityLevel(ds.dayMap[k],ds,k);return `<span class="heat level-${l}" title="${k}"></span>`}).join('')}</div><div class="calendar-legend"><span>lebih sedikit</span><span class="heat level-1"></span><span class="heat level-2"></span><span class="heat level-3"></span><span>lebih aktif</span></div></div>${sectionHead(`Shalat ${range} hari`)}<div class="card pad"><div class="bar-list">${prayers.map(p=>`<div class="bar-row"><div><b>${p.label}</b><small>${p.done}/${range} · jamaah ${p.jamaah} · masjid ${p.masjid}</small></div><div class="bar-track"><i style="width:${pct(p.done,range)}%"></i></div><b>${pct(p.done,range)}%</b></div>`).join('')}</div></div>${sectionHead('Ringkasan lainnya')}<div class="stat-grid"><div class="stat-box"><strong>${jamaah}</strong><span>shalat jamaah</span></div><div class="stat-box"><strong>${masjid}</strong><span>jamaah di masjid</span></div><div class="stat-box"><strong>${raw}</strong><span>rawatib tercatat</span></div><div class="stat-box"><strong>${dhuha}</strong><span>hari Dhuha</span></div><div class="stat-box"><strong>${tahajud}</strong><span>hari Tahajud</span></div><div class="stat-box"><strong>${witir}</strong><span>hari Witir</span></div><div class="stat-box"><strong>${fast}</strong><span>hari puasa</span></div><div class="stat-box"><strong>${murPages}</strong><span>hlm murojaah</span></div></div>`}
  function targetsPage(ds){const t=state.settings.targets;return `${routeBack()}<section class="page-head compact"><h1>Target & Streak</h1><p>Pilih sendiri apa yang dihitung sebagai target konsistensi.</p></section><div class="card pad"><form id="targetsForm" class="form-grid">${targetToggle('prayer5','Shalat wajib 5 waktu',t.prayer5)}${targetToggle('tilawah','Tilawah harian',t.tilawah,`<input class="form-input mini-input" type="number" name="tilawahPages" min="1" value="${t.tilawahPages||5}"> hlm`)}${targetToggle('dzikirPagi','Dzikir pagi',t.dzikirPagi)}${targetToggle('dhuha','Dhuha',t.dhuha)}${targetToggle('murojaah','Murojaah harian',t.murojaah,`<input class="form-input mini-input" type="number" name="murojaahAyat" min="1" value="${t.murojaahAyat||10}"> ayat`)}<button class="primary-btn">Simpan target</button></form></div>${sectionHead('Streak saat ini')}<div class="stat-grid"><div class="stat-box"><strong>🔥 ${streakFrom(ds)}</strong><span>target utama</span></div><div class="stat-box"><strong>📖 ${streakFrom(ds,'tilawah')}</strong><span>tilawah</span></div><div class="stat-box"><strong>🧠 ${streakFrom(ds,'murojaah')}</strong><span>murojaah</span></div></div>`}
  function targetToggle(name,label,on,extra=''){return `<label class="toggle-row"><span><b>${label}</b>${extra?`<small>${extra}</small>`:''}</span><input type="checkbox" name="${name}" ${on?'checked':''}><i></i></label>`}
  function qadhaPage(ds){const done=ds.days.filter(d=>d.fast?.active&&d.fast.type==='Qadha').length,left=Math.max(0,(state.settings.qadhaInitial||0)-done);return `${routeBack()}<section class="page-head compact"><h1>Qadha Puasa</h1></section><div class="card pad hero-progress"><span class="eyebrow">SISA QADHA</span><h2>${left} hari</h2><div class="progress-track"><div class="progress-fill" style="width:${pct(done,state.settings.qadhaInitial||1)}%"></div></div><p>${done} dari ${state.settings.qadhaInitial||0} hari selesai</p></div><div class="card pad"><form id="qadhaForm" class="form-grid"><label>Utang puasa awal<input class="form-input" type="number" min="0" name="initial" value="${state.settings.qadhaInitial||0}"></label><p class="muted small">Setiap hari yang kamu tandai sebagai Puasa → Qadha otomatis mengurangi sisa.</p><button class="primary-btn">Simpan</button></form></div>`}
  function doaPage(){return `${routeBack()}<section class="page-head compact"><h1>Kumpulan Doa</h1><p>Transliterasi menggunakan gaya Indonesia.</p></section><div class="stack">${DOAS.map(d=>`<article class="card doa-card"><h3>${d.title}</h3><div class="arabic">${d.arab}</div><p class="latin">${d.latin}</p><p class="muted">${d.arti}</p></article>`).join('')}</div>`}
  function customManager(){const hs=state.settings.customHabits||[];return `${routeBack()}<section class="page-head compact"><h1>Ibadah Custom</h1><p>Tambahkan tracker sesuai kebutuhanmu.</p></section><div class="card pad"><form id="customHabitForm" class="form-grid"><label>Nama<input class="form-input" name="name" required placeholder="Contoh: Al-Kahfi Jumat"></label><label>Jenis<select class="form-select" name="type"><option value="check">Checklist</option><option value="count">Jumlah</option></select></label><div class="two"><label>Unit<input class="form-input" name="unit" placeholder="kali / menit / halaman"></label><label>Target<input class="form-input" name="target" type="number" min="0"></label></div><button class="primary-btn">Tambah tracker</button></form></div>${sectionHead('Tracker aktif')}${hs.length?`<div class="card settings-list">${hs.map(h=>`<div class="setting-row simple"><div class="setting-icon">＋</div><div class="grow"><b>${esc(h.name)}</b><p>${h.type==='check'?'Checklist':'Jumlah'}${h.target?` · target ${h.target} ${esc(h.unit||'')}`:''}</p></div><button class="icon-btn danger-text" data-action="delete-custom" data-id="${h.id}">×</button></div>`).join('')}</div>`:emptyState('＋','Belum ada tracker','Tambahkan tracker pertamamu dari form di atas.')}`}
  function personalization(){return `${routeBack()}<section class="page-head compact"><h1>Personalisasi</h1></section><div class="card pad"><form id="personalForm" class="form-grid"><label>Nama aplikasi<input class="form-input" name="appName" value="${esc(state.settings.appName)}"></label><label>Nama panggilan<input class="form-input" name="nickname" value="${esc(state.settings.nickname)}"></label><label>Tagline<input class="form-input" name="tagline" value="${esc(state.settings.tagline)}"></label><label>Lokasi<input class="form-input" name="location" value="${esc(state.settings.location)}"></label><div class="two"><label>Target tilawah/ hari<input class="form-input" type="number" min="1" name="quranDailyTarget" value="${state.settings.quranDailyTarget||5}"></label><label>Target murojaah/ hari<input class="form-input" type="number" min="1" name="murojaahDailyTarget" value="${state.settings.murojaahDailyTarget||10}"></label></div><label>Warna utama<div class="color-row"><input class="form-input" name="accent" value="${esc(state.settings.accent)}"><input type="color" name="accentPicker" value="${esc(state.settings.accent)}"></div></label><button class="primary-btn">Simpan personalisasi</button></form></div>`}
  function prayerSettings(){return `${routeBack()}<section class="page-head compact"><h1>Waktu Shalat</h1><p>Versi GitHub ini memakai waktu manual yang bisa kamu edit.</p></section><div class="card pad"><form id="prayerForm" class="form-grid">${Object.keys(state.settings.prayerTimes).map(id=>`<label>${state.settings.prayerLabels[id]}<input class="form-input" type="time" name="${id}" value="${state.settings.prayerTimes[id]}"></label>`).join('')}<button class="primary-btn">Simpan waktu shalat</button></form></div>`}
  function displaySettings(){return `${routeBack()}<section class="page-head compact"><h1>Tampilan</h1></section><div class="card pad"><label class="toggle-row"><span><b>Mode gelap</b><small>Tersimpan di perangkat ini</small></span><input id="darkToggle" type="checkbox" ${state.settings.darkMode?'checked':''}><i></i></label></div>`}
  function backupPage(ds){return `${routeBack()}<section class="page-head compact"><h1>Data & Backup</h1><p>Data utama berada di IndexedDB perangkat ini. GitHub hanya menyimpan kode.</p></section><div class="card pad"><div class="backup-summary"><div><b>${ds.days.length}</b><span>hari</span></div><div><b>${ds.tilawah.length}</b><span>tilawah</span></div><div><b>${ds.murojaah.length}</b><span>murojaah</span></div><div><b>${ds.journal.length}</b><span>jurnal</span></div></div><div class="button-stack"><button class="primary-btn" data-action="export-backup">Buat Backup JSON</button><button class="ghost-btn" data-action="import-backup">Pulihkan dari Backup</button><button class="ghost-btn" data-action="share-backup">Bagikan Backup</button></div></div><div class="card pad"><span class="eyebrow">GOOGLE DRIVE</span><h2>Siap dihubungkan</h2><p class="muted">Backup otomatis ke Drive membutuhkan Google OAuth Client ID untuk domain GitHub Pages milikmu. Struktur backup Atsar sudah kompatibel; setelah Client ID diisi, integrasi Drive bisa ditambahkan tanpa mengubah format data.</p><div class="notice">Saat ini gunakan <b>Buat Backup JSON</b>, lalu simpan file tersebut ke Google Drive. Restore dapat dilakukan langsung dari file JSON.</div></div><button class="danger-outline full" data-action="reset-all">Hapus semua data Atsar</button>`}

  async function render(){applyTheme();$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.route===state.route));view.innerHTML='<div class="loading">Memuat Atsar…</div>';let html='';if(state.route==='home')html=await home();else if(state.route==='ibadah')html=await ibadah();else if(state.route==='quran')html=await quran();else if(state.route==='aktivitas')html=await aktivitas();else html=await profil();view.innerHTML=html;window.scrollTo({top:0,behavior:'instant'})}

  async function mutateDay(fn){const day=await dayData();fn(day);await AtsarDB.saveDay(day);await render()}
  function formObj(form){return Object.fromEntries(new FormData(form).entries())}
  function todayKey(){return keyOf(new Date())}

  document.addEventListener('click',async e=>{
    if(e.target.closest('[data-stop]')) e.stopPropagation();
    const route=e.target.closest('[data-route]');if(route){state.route=route.dataset.route;state.profilePage='menu';await render();return}
    const dt=e.target.closest('[data-date]');if(dt){state.selectedDate=dt.dataset.date;if(state.route==='aktivitas')state.route='ibadah';await render();return}
    const it=e.target.closest('[data-ibadah-tab]');if(it){state.ibadahTab=it.dataset.ibadahTab;await render();return}
    const qt=e.target.closest('[data-quran-tab]');if(qt){state.quranTab=qt.dataset.quranTab;state.route='quran';await render();return}
    const pp=e.target.closest('[data-profile-page]');if(pp){if(pp.dataset.profilePage==='quran'){state.route='quran';state.quranTab='dashboard';state.profilePage='menu'}else if(pp.dataset.profilePage==='murojaah'){state.route='quran';state.quranTab='murojaah';state.profilePage='menu'}else state.profilePage=pp.dataset.profilePage;await render();return}
    const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;
    if(act==='close-modal'){closeModal();return} if(act==='profile-menu'){state.profilePage='menu';await render();return} if(act==='render'){await render();return} if(act==='stats-range'){state.statsRange=Number(a.dataset.range)||30;await render();return}
    if(act==='toggle-prayer'){await mutateDay(d=>d.prayers[a.dataset.prayer].done=!d.prayers[a.dataset.prayer].done);return}
    if(act==='prayer-mode'){await mutateDay(d=>d.prayers[a.dataset.prayer].mode=a.dataset.mode);return}
    if(act==='rawatib'){await mutateDay(d=>d.prayers[a.dataset.prayer][a.dataset.slot]=!d.prayers[a.dataset.prayer][a.dataset.slot]);return}
    if(act==='sunnah-inc'||act==='sunnah-dec'){await mutateDay(d=>d.sunnah[a.dataset.id]=Math.max(0,Number(d.sunnah[a.dataset.id]||0)+(act==='sunnah-inc'?2:-2)));return}
    if(act==='sunnah-toggle'){await mutateDay(d=>d.sunnah[a.dataset.id]=!d.sunnah[a.dataset.id]);return}
    if(act==='fast-toggle'){await mutateDay(d=>d.fast.active=!d.fast.active);return}
    if(act==='fast-type'){await mutateDay(d=>{d.fast.active=true;d.fast.type=a.dataset.fast});return}
    if(act==='open-qadha'){state.route='profil';state.profilePage='qadha';await render();return}
    if(act==='dzikir-add'){await mutateDay(d=>d.dzikir[a.dataset.kind]=Number(d.dzikir[a.dataset.kind]||0)+Number(a.dataset.num));return}
    if(act==='dzikir-reset'){await mutateDay(d=>d.dzikir[a.dataset.kind]=0);return}
    if(act==='custom-check'){await mutateDay(d=>{d.custom=d.custom||{};d.custom[a.dataset.id]=d.custom[a.dataset.id]?0:1});return}
    if(act==='custom-inc'||act==='custom-dec'){await mutateDay(d=>{d.custom=d.custom||{};d.custom[a.dataset.id]=Math.max(0,Number(d.custom[a.dataset.id]||0)+(act==='custom-inc'?1:-1))});return}
    if(act==='profile-custom'){state.route='profil';state.profilePage='custom';await render();return}
    if(act==='quick-tilawah'){await addTilawah(Number(a.dataset.num));return}
    if(act==='quick-tilawah-custom'){const n=Number($('#quickPages')?.value||0);if(n>0)await addTilawah(n);else showToast('Masukkan jumlah halaman.');return}
    if(act==='delete-tilawah'){if(confirm('Hapus catatan tilawah ini?')){await AtsarDB.del('tilawah',Number(a.dataset.id));showToast('Catatan dihapus.');await render()}return}
    if(act==='delete-murojaah'){if(confirm('Hapus catatan murojaah ini?')){await AtsarDB.del('murojaah',Number(a.dataset.id));showToast('Catatan dihapus.');await render()}return}
    if(act==='cal-prev'){state.calendarCursor=new Date(state.calendarCursor.getFullYear(),state.calendarCursor.getMonth()-1,1);await render();return}
    if(act==='cal-next'){state.calendarCursor=new Date(state.calendarCursor.getFullYear(),state.calendarCursor.getMonth()+1,1);await render();return}
    if(act==='save-journal'){await AtsarDB.put('journal',{date:state.selectedDate,text:$('#journalText').value,updatedAt:new Date().toISOString()});showToast('Catatan tersimpan.');return}
    if(act==='delete-custom'){state.settings.customHabits=(state.settings.customHabits||[]).filter(h=>h.id!==a.dataset.id);saveSettings('Tracker dihapus.');return}
    if(act==='export-backup'){await exportBackup(false);return}
    if(act==='share-backup'){await exportBackup(true);return}
    if(act==='import-backup'){importFile.click();return}
    if(act==='reset-all'){if(confirm('Hapus SEMUA data Atsar di perangkat ini? Backup dulu jika perlu.')){await AtsarDB.clearAll();localStorage.removeItem('atsar.settings.v2');state.settings=AtsarDB.settings();showToast('Semua data dihapus.');await render()}return}
    if(act==='restore-merge'||act==='restore-replace'){try{await AtsarDB.importAll(state.backupPayload,act==='restore-merge'?'merge':'replace');state.settings=AtsarDB.settings();closeModal();showToast('Backup berhasil dipulihkan.');await render()}catch(err){showToast(err.message)}return}
  });

  document.addEventListener('submit',async e=>{
    e.preventDefault();const f=e.target,d=formObj(f);
    if(f.id==='tilawahForm'){const pages=Number(d.pages||0);if(!pages)return;await AtsarDB.add('tilawah',{date:todayKey(),surah:d.surah,juz:d.juz?Number(d.juz):null,pages,startPage:d.startPage?Number(d.startPage):null,endPage:d.endPage?Number(d.endPage):null,note:d.note||'',createdAt:new Date().toISOString()});showToast('Tilawah tersimpan.');await render();return}
    if(f.id==='murojaahForm'){const qm=qualityMeta(d.quality),date=todayKey(),next=keyOf(addDays(new Date(),qm[2]));const sp=d.startPage?Number(d.startPage):null,ep=d.endPage?Number(d.endPage):null;await AtsarDB.add('murojaah',{date,surah:d.surah,startAyah:d.startAyah?Number(d.startAyah):null,endAyah:d.endAyah?Number(d.endAyah):null,startPage:sp,endPage:ep,pages:sp&&ep&&ep>=sp?ep-sp+1:0,quality:d.quality,nextReview:next,note:d.note||'',createdAt:new Date().toISOString()});showToast(`Murojaah disimpan · ulang ${qm[2]} hari lagi.`);await render();return}
    if(f.id==='targetsForm'){state.settings.targets={prayer5:f.prayer5.checked,tilawah:f.tilawah.checked,tilawahPages:Number(d.tilawahPages||5),dzikirPagi:f.dzikirPagi.checked,dhuha:f.dhuha.checked,murojaah:f.murojaah.checked,murojaahAyat:Number(d.murojaahAyat||10)};saveSettings('Target tersimpan.');return}
    if(f.id==='qadhaForm'){state.settings.qadhaInitial=Number(d.initial||0);saveSettings('Qadha diperbarui.');return}
    if(f.id==='customHabitForm'){const id='h'+Date.now();state.settings.customHabits=state.settings.customHabits||[];state.settings.customHabits.push({id,name:d.name,type:d.type,unit:d.unit||'',target:Number(d.target||0)});saveSettings('Tracker ditambahkan.');return}
    if(f.id==='personalForm'){state.settings.appName=d.appName||'Atsar';state.settings.nickname=d.nickname||'Ibe';state.settings.tagline=d.tagline||'';state.settings.location=d.location||'';state.settings.quranDailyTarget=Number(d.quranDailyTarget||5);state.settings.murojaahDailyTarget=Number(d.murojaahDailyTarget||10);state.settings.accent=d.accent||'#195d63';saveSettings('Personalisasi tersimpan.');return}
    if(f.id==='prayerForm'){Object.keys(state.settings.prayerTimes).forEach(id=>state.settings.prayerTimes[id]=d[id]);saveSettings('Waktu shalat tersimpan.');return}
  });
  document.addEventListener('change',async e=>{if(e.target.id==='darkToggle'){state.settings.darkMode=e.target.checked;saveSettings('Tampilan diperbarui.');return}if(e.target.name==='accentPicker'){const text=$('[name="accent"]');if(text)text.value=e.target.value}}
  );

  async function addTilawah(pages){await AtsarDB.add('tilawah',{date:todayKey(),pages,surah:'',juz:null,startPage:null,endPage:null,note:'Quick add',createdAt:new Date().toISOString()});showToast(`+${pages} halaman tersimpan.`);await render()}
  function saveSettings(msg){AtsarDB.saveSettings(state.settings);applyTheme();showToast(msg);render()}

  async function exportBackup(share){const payload=await AtsarDB.exportAll(),json=JSON.stringify(payload,null,2),name=`atsar-backup-${todayKey()}.json`,blob=new Blob([json],{type:'application/json'}),file=new File([blob],name,{type:'application/json'});if(share&&navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({title:'Backup Atsar',files:[file]});return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast(share?'Perangkat tidak mendukung share file; backup diunduh.':'Backup JSON dibuat.')}
  importFile.addEventListener('change',async()=>{const file=importFile.files[0];if(!file)return;try{const p=JSON.parse(await file.text());state.backupPayload=p;const stores=p.stores||{};const days=p.version===1?Object.keys(p.days||{}).length:(stores.days||[]).length,til=p.version===1?Object.values(p.days||{}).filter(x=>Number(x?.tilawah?.pages||0)>0).length:(stores.tilawah||[]).length,mur=(stores.murojaah||[]).length;openModal(`<span class="eyebrow">PREVIEW BACKUP</span><h2>${esc(file.name)}</h2><p class="muted">${p.exportedAt?fmt(new Date(p.exportedAt),{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Tanggal tidak tersedia'}</p><div class="backup-summary"><div><b>${days}</b><span>hari</span></div><div><b>${til}</b><span>tilawah</span></div><div><b>${mur}</b><span>murojaah</span></div></div><div class="notice"><b>Gabungkan</b> mempertahankan data perangkat. <b>Ganti seluruh data</b> membuat kondisi Atsar sama seperti backup.</div><div class="button-stack"><button class="primary-btn" data-action="restore-merge">Gabungkan data</button><button class="danger-outline" data-action="restore-replace">Ganti seluruh data</button><button class="ghost-btn" data-action="close-modal">Batal</button></div>`)}catch(err){showToast('File backup tidak valid.')}finally{importFile.value=''}});

  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredInstall=e;installBtn.hidden=false});installBtn.addEventListener('click',async()=>{if(!state.deferredInstall)return;state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;installBtn.hidden=true});
  if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js'));

  (async()=>{await AtsarDB.openDB();await AtsarDB.migrateV1();state.settings=AtsarDB.settings();applyTheme();await render()})().catch(err=>{console.error(err);view.innerHTML=`<div class="card pad"><h2>Atsar gagal dimuat</h2><p>${esc(err.message)}</p></div>`});
})();
